sys_script_include.script:
// MSSTRESURY-555
// Utility class for preparing and sending MT103/MT202 SWIFT message payloads to ITM
// Provides modular functions for payload construction, outbound storage, and ITM integration

var MSS_Treasury_ITM_Utils = Class.create();
MSS_Treasury_ITM_Utils.prototype = {
    // Constructor
    initialize: function() {
        var env = gs.getProperty('x_hsb11_mss_tsd.itm_base_endpoint');
        var token = gs.getProperty('x_hsb11_mss_tsd.itm_api_token');


        this.env = env;
        this.token = token;
    },

    // Generates and sends instruction JSON for MT103 or MT202 based on case data
    generateInstructionJSON: function(caseSysid, messageID, objID, swiftMessage) {
        try {
            // Retrieve the Treasury Case record
            var grCase = new GlideRecord('x_hsb11_mss_tsd_treasury_case');

            if (grCase.get(caseSysid)) {
                // Use sourceType parameter if provided, else fall back to case record
                var messageType = swiftMessage || grCase.getDisplayValue('swift_message');
                var messageJSON = '';

                // Prepare payload for the specified message type
                switch (messageType) {
                    case 'MT103':
                        messageJSON = this.prepareMT103Payload(
                            grCase.getValue('source_type'),
                            grCase.getValue('senderbic'),
                            grCase.getValue('transaction_reference'),
                            this.formatDate(grCase.getValue('value_date')),
                            grCase.getDisplayValue('currency'),
                            this.removeCommas(grCase.getValue('transaction_amount')),
                            grCase.getValue('customer_order_type'),
                            grCase.getValue('bank_operation_code'),
                            grCase.getValue('instructed_amount'),
                            grCase.getValue('instructed_currency'),
                            grCase.getValue('ordering_customer_bic'),
                            grCase.getValue('ordering_customer_name'),
                            grCase.getValue('ordering_customer_address'),
                            grCase.getValue('ordering_customer_identifier_code'),
                            grCase.getValue('ordering_institution_bic'),
                            grCase.getValue('ordering_institution_name'),
                            grCase.getValue('ordering_institution_address'),
                            grCase.getValue('ordering_institution_identifier_code'),
                            grCase.getValue('sender_s_correspondent_bic'),
                            grCase.getValue('sender_s_correspondent_name'),
                            grCase.getValue('sender_s_correspondent_address'),
                            grCase.getValue('sender_s_correspondent_identifier_code'),
                            grCase.getValue('sender_s_correspondent_location'),
                            grCase.getValue('receiver_s_correspondent_bic'),
                            grCase.getValue('receiver_s_correspondent_name'),
                            grCase.getValue('receiver_s_correspondent_address'),
                            grCase.getValue('receiver_s_correspondent_identifier_code'),
                            grCase.getValue('receiver_s_correspondent_location'),
                            grCase.getValue('intermediary_bank_bic'),
                            grCase.getValue('intermediary_bank_name'),
                            grCase.getValue('intermediary_bank_address'),
                            grCase.getValue('intermediary_bank_identifier_code'),
                            grCase.getValue('beneficiary_bank_bic'),
                            grCase.getValue('beneficiary_bank_name'),
                            grCase.getValue('beneficiary_bank_address'),
                            grCase.getValue('beneficiary_bank_identifier_code'),
                            grCase.getValue('beneficiary_institution_bic'),
                            grCase.getValue('beneficiary_institution_name'),
                            grCase.getValue('beneficiary_institution_address'),
                            grCase.getValue('beneficiary_institution_identifier_code'),
                            grCase.getValue('beneficiary_customer_bic'),
                            grCase.getValue('beneficiary_customer_name'),
                            grCase.getValue('beneficiary_customer_identifier_code'),
                            grCase.getValue('beneficiary_customer_address'),
                            grCase.getValue('remittance_information'),
                            grCase.getValue('details_of_charge'),
                            grCase.getValue('sender_to_receiver_information'),
                            grCase.getValue('first_received_timestamp'),
                            grCase.getValue('receiverbic'),
                            grCase.getValue('swift_message')
                        );
                        break;

                    case 'MT202':
                        messageJSON = this.prepareMT202Payload(
                            grCase.getValue('source_type'),
                            grCase.getValue('senderbic'),
                            grCase.getValue('transaction_reference'),
                            (grCase.getValue('related_reference') ? String(grCase.getValue('related_reference')) : ''), // Ensure string type
                            this.formatDate(grCase.getValue('value_date')),
                            grCase.getDisplayValue('currency'),
                            this.removeCommas(grCase.getValue('transaction_amount')),
                            grCase.getValue('customer_order_type'),
                            grCase.getValue('ordering_institution_bic'),
                            grCase.getValue('ordering_institution_name'),
                            grCase.getValue('ordering_institution_address'),
                            grCase.getValue('ordering_institution_identifier_code'),
                            grCase.getValue('sender_s_correspondent_bic'),
                            grCase.getValue('sender_s_correspondent_name'),
                            grCase.getValue('sender_s_correspondent_address'),
                            grCase.getValue('sender_s_correspondent_identifier_code'),
                            grCase.getValue('sender_s_correspondent_location'),
                            grCase.getValue('intermediary_bank_bic'),
                            grCase.getValue('intermediary_bank_name'),
                            grCase.getValue('intermediary_bank_address'),
                            grCase.getValue('intermediary_bank_identifier_code'),
                            grCase.getValue('beneficiary_bank_bic'),
                            grCase.getValue('beneficiary_bank_name'),
                            grCase.getValue('beneficiary_bank_address'),
                            grCase.getValue('beneficiary_bank_identifier_code'),
                            grCase.getValue('beneficiary_institution_bic'),
                            grCase.getValue('beneficiary_institution_name'),
                            grCase.getValue('beneficiary_institution_address'),
                            grCase.getValue('beneficiary_institution_identifier_code'),
                            grCase.getValue('sender_to_receiver_information'),
                            grCase.getValue('first_received_timestamp'),
                            grCase.getValue('receiverbic'),
                            grCase.getValue('swift_message')
                        );
                        break;

                    default:
                        return;
                }

                // Generate ITM header
                // Parse the messageJSON string to an object for payload
                var parsedPayload = {};
                try {
                    parsedPayload = JSON.parse(messageJSON);
                } catch (e) {
                    gs.error('Failed to parse messageJSON: ' + e.message);
                }
                const itmHeader = this.createItmHeader(
                    grCase.getValue('u_objectid'),
                    grCase.getValue('legal_entity') || '',
                    'create',
                    messageType,
                    '', // owningBusiness not used, pass empty string
                    parsedPayload // pass the parsed payload object
                );
                const outboundSysId = this.storePayloadInOutboundTable(itmHeader, messageType, 'Post Payload', caseSysid);
                if (!outboundSysId) {
                    return;
                }
                const result = this.sendToITM(outboundSysId);
                grCase.event_status = 'Instruction Sent';
                grCase.update();
            }
        } catch (e) {
            this.errorLogAndXmatterAlert("WARNING", 'Error in generateInstructionJSON: ' + e.message);
        }
    },

    // Stores the generated payload in the MSS Event Outbound table
    storePayloadInOutboundTable: function(payload, messageType, requestType, caseSysid) {
        try {
            const grOutbound = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_outbound');
            grOutbound.initialize();
            grOutbound.request_body = JSON.stringify(payload);
            grOutbound.request_date = new GlideDateTime();
            grOutbound.request_type = requestType;
            grOutbound.state = 'Pending';
            var treasurysourceTable = 'x_hsb11_mss_tsd_treasury_case';
            var treasurySource = gs.getProperty('x_hsb11_mss_tsd.mss.treasury.core.scope.id');
            grOutbound.sys_scope = treasurySource;
            grOutbound.source_table = treasurysourceTable;
            grOutbound.document_id = caseSysid;
            const sysId = grOutbound.insert();
            if (!sysId) {
                this.errorLogAndXmatterAlert("MINOR", 'Failed to insert record into MSS Event Outbound table.');
            }
            return sysId;
        } catch (error) {
            this.errorLogAndXmatterAlert("MINOR", 'Error storing payload in MSS Event Outbound table: ' + error.message);
            return null;
        }
    },

    // Sends payload to ITM via REST API
    // This function retrieves the outbound record, sends the payload to the ITM API, and updates the record status based on the response.
    sendToITM: function(outboundSysId) {
        try {
            // Retrieve the outbound record by SysID
            const gr = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_outbound');
            if (gr.get(outboundSysId)) {
                // Prepare REST message for ITM API
                const r = new sn_ws.RESTMessageV2('ITM Outbound Api', 'ITM Instruction Outbound');
                r.setStringParameterNoEscape("itm_api_token", this.token);
                r.setStringParameterNoEscape("base_itm_endpoint", this.env);
                r.setStringParameterNoEscape("itm_instruction_api", gs.getProperty('x_hsb11_mss_tsd.itm_instruction_api'));
                const toSend = gr.request_body; // Get the payload to send
                r.setRequestBody(toSend); // Set the request body
                gr.state = 'Processing'; // Mark as processing
                gr.request_date = new GlideDateTime(); // Update request date
                gr.update();

                // Execute the REST call
                const response = r.execute();
                const responseBody = response.getBody();
                const httpStatus = response.getStatusCode();
                gs.info('ITM SEND: outboundSysId=' + outboundSysId + ', httpStatus=' + httpStatus + ', responseBody=' + responseBody);

                // Update the outbound record based on the response
                if (httpStatus == '200') {
                    gr.response_body = responseBody;
                    gr.state = 'Processed';
                    gr.error_body = '';
                    gr.error_code = '';
                } else if (httpStatus == '429' || httpStatus == '500' || httpStatus == '502') { //added as part of MSSTRESURY-806 Development
                    var count = gr.getValue("retry_count");
                    if (count < 3) {
                        count++;
                        gr.retry_count = count;
                        gr.state = "Retrying";
                        gr.error_body = responseBody;
                        gr.error_code = httpStatus;
                        var processTime = new GlideDateTime;
                        processTime.addSeconds(300);
                        gs.eventQueueScheduled('x_hsb11_mss_tsd.Treasury_ITM_Outbound', gr, gr.sys_id, '', processTime);
                    } else {
                        gr.error_body = responseBody;
                        gr.error_code = httpStatus;
                        gr.state = 'Error';
                        gr.update();
                        throw new Error('Max retries reached (counter=' + count + ') HTTP ' + httpStatus + ' outbound_sys_id=' + outboundSysId);
                    }
                } else {
                    gr.error_body = responseBody;
                    gr.error_code = httpStatus;
                    gr.state = 'Error';
                }

                gr.response_date = new GlideDateTime(); // Set response date
                gr.update();
            } else {
                // Outbound record not found
                throw new Error('Outbound record not found for SysID: ' + outboundSysId);
            }
        } catch (e) {
            // Log any errors that occur during the process
            const errorMessage = 'Error in sendToITM: ' + e.message;
            this.errorLogAndXmatterAlert("MINOR", errorMessage);
        }
    },

    // Constructs the MT103 payload according to SWIFT/CMF rules
    // This function builds the full MT103 message structure, including all required tags and fields.
    // It uses helper functions to add party and account details in the correct SWIFT/CMF order.
    // Returns a JSON string representing the MT103 payload.
    prepareMT103Payload: function(source_type, senderbic, transactionReference, valuedate, currency, transactionAmount, customerOrderType, bankOperationCode, instructedAmount, instructedCurrency, orderingCustomerBIC, orderingCustomerName, orderingCustomerAddress, orderingCustomerIdentifierCode, orderingInstitutionBIC, orderingInstitutionName, orderingInstitutionAddress, orderingInstitutionIdentifierCode, sendersCorrespondentBIC, sendersCorrespondentName, sendersCorrespondentAddress, sendersCorrespondentIdentifierCode, sendersCorrespondentLocation, receiversCorrespondentBIC, receiversCorrespondentName, receiversCorrespondendentAddress, receiversCorrespondentIdentifierCode, receiversCorrespondentLocation, intermediaryBankBIC, intermediaryBankName, intermediaryBankAddress, intermediaryBankIdentifierCode, beneficiaryBankBIC, beneficiaryBankName, beneficiaryBankAddress, beneficiaryBankIdentifierCode, beneficiaryInstitutionBIC, beneficiaryInstitutionName, beneficiaryInstitutionAddress, beneficiaryInstitutionIdentifierCode, beneficiaryCustomerBIC, beneficiaryCustomerName, beneficiaryCustomerIdentifierCode, beneficiaryCustomerAddress, remittanceInformation, detailsOfCharge, senderToReceiverInformation, firstReceivedTimestamp, receiverbic, swift_message) {
        try {
            // Helper to parse outputDate/outputTime from First Received Timestamp
            var outputDate = ''; // Initialize outputDate as empty string
            var outputTime = ''; // Initialize outputTime as empty string
            if (firstReceivedTimestamp && typeof firstReceivedTimestamp === 'string') { // Check if firstReceivedTimestamp exists and is a string
                var dateMatch = firstReceivedTimestamp.match(/(\d{4}-\d{2}-\d{2})/); // Extract date in yyyy-MM-dd format
                var timeMatch = firstReceivedTimestamp.match(/(\d{2})\.(\d{2})\.\d{2}/); // Only extract hour and minute
                if (dateMatch) outputDate = dateMatch[1]; // If date found, assign to outputDate
                if (timeMatch) {
                    outputTime = timeMatch[1] + timeMatch[2]; // Format as HHMM (no colon)
                }
            }
            // Build the MT103 payload structure
            var body = {
                "wrapper": {
                    "transactions": {
                        "sourceName": source_type,
                        "clientShortName": (source_type === 'FAX' || source_type === 'EMAIL' || !senderbic || typeof senderbic !== 'string') ? 'NULL' : senderbic,
                        "trade": {
                            "tradeOrderDetails": {
                                "customerReference": transactionReference,
                                "customerOrderType": customerOrderType || "NEWM",
                                "orderValueDate": valuedate,
                                "orderTransactionDetails": {
                                    "orderAmountDetail": [{
                                            "amountType": "32A",
                                            "amount": transactionAmount,
                                            "currencyDetails": {
                                                "currencyCode": currency
                                            }
                                        },
                                        {
                                            "amountType": "33B",
                                            "amount": instructedAmount,
                                            "currencyDetails": {
                                                "currencyCode": instructedCurrency
                                            }
                                        }
                                    ]
                                }
                            },
                            "tradeComments": {
                                "comments": [
                                    // Tag 72: Sender to Receiver Information
                                    senderToReceiverInformation && senderToReceiverInformation.trim() !== '' ? (function() {
                                        // Upstream now splits at 35 chars using newlines. Convert any newline(s) to '|'
                                        var comment72 = senderToReceiverInformation
                                            .replace(/\\n+/g, '|') // literal \n → |
                                            .replace(/\r?\n+/g, '|') // real newlines → |
                                            .replace(/\|+/g, '|') // collapse multiple |
                                            .trim();
                                        return {
                                            "commentType": "72",
                                            "comment": comment72
                                        };
                                    })() : undefined,
                                    // Tag 71: Details of Charge
                                    detailsOfCharge && detailsOfCharge.trim() !== '' ? {
                                        "commentType": detailsOfCharge === 'BEN' ? "71F" : "71A",
                                        "comment": detailsOfCharge
                                    } : undefined
                                ].filter(Boolean),
                            },
                            "partiesInvolved": {
                                "partyRoleDetails": []
                            },
                            "accountsInvolved": {
                                "tradeAccountDetails": []
                            },
                            "cashTrade": {
                                "transactionType": "PAYM",
                                "transactionSubType": "CTRF"
                            },
                            "tradeSuplDetails": {
                                "otherSuplDetails": [{
                                    "fieldName": "23B",
                                    "fieldValue": bankOperationCode || "CRED"
                                }],
                                "swiftOtherDetail": [].concat(
                                    // Include outputDate and outputTime only if they have values
                                    (function() {
                                        var details = [];
                                        if (outputDate) {
                                            details.push({
                                                "fieldName": "outputDate",
                                                "swiftFieldName": "2",
                                                "fieldValue": outputDate
                                            });
                                        }
                                        if (outputTime) {
                                            details.push({
                                                "fieldName": "outputTime",
                                                "swiftFieldName": "2",
                                                "fieldValue": outputTime
                                            });
                                        }
                                        return details;
                                    })(),
                                    [{
                                            "fieldName": "msgType",
                                            "swiftFieldName": "2",
                                            // Extracts the numeric part from swift_message (e.g., 'MT103' -> '103').
                                            // If swift_message is already numeric or does not match, returns as is.
                                            "fieldValue": (function() {
                                                if (typeof swift_message === 'string') {
                                                    var match = swift_message.match(/MT(\d+)/i);
                                                    if (match && match[1]) {
                                                        return match[1];
                                                    }
                                                }
                                                // fallback: extract digits if present
                                                var digits = (swift_message + '').match(/\d+/);
                                                return digits ? digits[0] : swift_message;
                                            })()
                                        },
                                        {
                                            "fieldName": "senderBIC",
                                            "swiftFieldName": "2",
                                            "fieldValue": senderbic
                                        },
                                        {
                                            "fieldName": "receiverBIC",
                                            "swiftFieldName": "1",
                                            "fieldValue": receiverbic
                                        }
                                    ].filter(function(detail) {
                                        // Remove senderBIC/receiverBIC if value is null/empty
                                        if ((detail.fieldName === "senderBIC" || detail.fieldName === "receiverBIC") && (!detail.fieldValue || detail.fieldValue === '' || detail.fieldValue === null)) {
                                            return false;
                                        }
                                        return true;
                                    })
                                )
                            }
                        }
                    }
                }
            };

            // Helper functions
            // Adds a party with a specific role and BIC
            var addPartyRoleDetails = function(roleType, partyIdType, partyId) {
                if (partyId && partyId.trim() !== '') {
                    body.wrapper.transactions.trade.partiesInvolved.partyRoleDetails.push({
                        "partyRoleType": roleType,
                        "partyDetails": {
                            "partyIdentifiers": {
                                "partyIds": [{
                                    "partyIdType": partyIdType,
                                    "partyId": partyId
                                }]
                            }
                        }
                    });
                }
            };

            // Adds a party with a specific role and name (when BIC is not present)
            var addPartyNameDetails = function(roleType, partyName) {
                if (partyName && partyName.trim() !== '') {
                    var details = {
                        "partyRoleType": roleType,
                        "partyDetails": {
                            "partyName": partyName
                        }
                    };
                    body.wrapper.transactions.trade.partiesInvolved.partyRoleDetails.push(details);
                }
            };

            // Adds an account with a specific role and account number/identifier
            var addAccountDetails = function(roleType, accountNumber) {
                if (accountNumber && accountNumber.trim() !== '') {
                    body.wrapper.transactions.trade.accountsInvolved.tradeAccountDetails.push({
                        "accountRoleType": roleType,
                        "accountDetails": {
                            "accountId": accountNumber
                        }
                    });
                }
            };
            // --- Party/Account Tag Population (MT103, correct SWIFT/CMF order) ---
            // Tag 50: Ordering Customer
            // 50A: If BIC has value
            if (orderingCustomerBIC && orderingCustomerBIC.trim() !== '') {
                addAccountDetails('50A', orderingCustomerIdentifierCode);
                addPartyRoleDetails('50A', 'BIC', orderingCustomerBIC);
                // 50K: If BIC is empty and NAME has value
            } else if ((!orderingCustomerBIC || orderingCustomerBIC.trim() === '') && orderingCustomerName && orderingCustomerName.trim() !== '') {
                addAccountDetails('50K', orderingCustomerIdentifierCode);
                addPartyNameDetails('50K', orderingCustomerName);
            }

            // Tag 52: Ordering Institution
            // 52A: If BIC has value
            if (orderingInstitutionBIC && orderingInstitutionBIC.trim() !== '') {
                addAccountDetails('52A', orderingInstitutionIdentifierCode);
                addPartyRoleDetails('52A', 'BIC', orderingInstitutionBIC);
                // 52D: If BIC is empty and NAME has value
            } else if ((!orderingInstitutionBIC || orderingInstitutionBIC.trim() === '') && orderingInstitutionName && orderingInstitutionName.trim() !== '') {
                addAccountDetails('52D', orderingInstitutionIdentifierCode);
                addPartyNameDetails('52D', orderingInstitutionName);
            }

            // Tag 53: Sender's Correspondent
            // 53A: If both Account ID and BIC have value
            if (sendersCorrespondentIdentifierCode && sendersCorrespondentIdentifierCode.trim() !== '' && sendersCorrespondentBIC && sendersCorrespondentBIC.trim() !== '') {
                addAccountDetails('53A', sendersCorrespondentIdentifierCode);
                addPartyRoleDetails('53A', 'BIC', sendersCorrespondentBIC);
                // 53A: If only BIC has value
            } else if (sendersCorrespondentBIC && sendersCorrespondentBIC.trim() !== '') {
                addPartyRoleDetails('53A', 'BIC', sendersCorrespondentBIC);
                // 53B: If only account id has value
            } else if (sendersCorrespondentIdentifierCode && sendersCorrespondentIdentifierCode.trim() !== '') {
                addAccountDetails('53B', sendersCorrespondentIdentifierCode);
            }

            // Tag 54: Receiver's Correspondent
            // 54A: If both Account ID and BIC have value
            if (receiversCorrespondentIdentifierCode && receiversCorrespondentIdentifierCode.trim() !== '' && receiversCorrespondentBIC && receiversCorrespondentBIC.trim() !== '') {
                addAccountDetails('54A', receiversCorrespondentIdentifierCode);
                addPartyRoleDetails('54A', 'BIC', receiversCorrespondentBIC);
                // 54A: If account id is blank but BIC has value
            } else if ((!receiversCorrespondentIdentifierCode || receiversCorrespondentIdentifierCode.trim() === '') && receiversCorrespondentBIC && receiversCorrespondentBIC.trim() !== '') {
                addPartyRoleDetails('54A', 'BIC', receiversCorrespondentBIC);
            }

            // Tag 56: Intermediary Bank
            // 56A: If BIC has value
            if (intermediaryBankBIC && intermediaryBankBIC.trim() !== '') {
                addAccountDetails('56A', intermediaryBankIdentifierCode);
                addPartyRoleDetails('56A', 'BIC', intermediaryBankBIC);
                // 56D: If BIC is empty and NAME has value
            } else if ((!intermediaryBankBIC || intermediaryBankBIC.trim() === '') && intermediaryBankName && intermediaryBankName.trim() !== '') {
                addAccountDetails('56D', intermediaryBankIdentifierCode);
                addPartyNameDetails('56D', intermediaryBankName);
            }

            // Tag 57: Beneficiary Bank
            // 57A: If BIC has value
            if (beneficiaryBankBIC && beneficiaryBankBIC.trim() !== '') {
                addAccountDetails('57A', beneficiaryBankIdentifierCode);
                addPartyRoleDetails('57A', 'BIC', beneficiaryBankBIC);
                // 57D: If BIC is empty and NAME has value
            } else if ((!beneficiaryBankBIC || beneficiaryBankBIC.trim() === '') && beneficiaryBankName && beneficiaryBankName.trim() !== '') {
                addAccountDetails('57D', beneficiaryBankIdentifierCode);
                addPartyNameDetails('57D', beneficiaryBankName);
            }

            // Tag 59: Beneficiary Customer
            // 59: If BIC is empty and NAME has value
            if ((!beneficiaryCustomerBIC || beneficiaryCustomerBIC.trim() === '') && beneficiaryCustomerName && beneficiaryCustomerName.trim() !== '') {
                addAccountDetails('59', beneficiaryCustomerIdentifierCode);
                addPartyNameDetails('59', beneficiaryCustomerName);
                // 59A: If BIC has value
            } else if (beneficiaryCustomerBIC && beneficiaryCustomerBIC.trim() !== '') {
                addAccountDetails('59A', beneficiaryCustomerIdentifierCode);
                addPartyRoleDetails('59A', 'BIC', beneficiaryCustomerBIC);
            }


            // --- Remove blank/empty fields from tradeSuplDetails.otherSuplDetails ---
            body.wrapper.transactions.trade.tradeSuplDetails.otherSuplDetails = body.wrapper.transactions.trade.tradeSuplDetails.otherSuplDetails.filter(function(detail) {
                return detail.fieldValue && detail.fieldValue.trim() !== '';
            });

            // Tag 70: Remittance Information
            if (remittanceInformation && remittanceInformation.trim() !== '') {
                // Upstream now splits at 35 chars using newlines. Convert any newline(s) to '|'
                var comment70 = remittanceInformation.replace(/\\n+/g, '|') // literal \n → |
                    .replace(/\r?\n+/g, '|') // real newlines → |
                    .replace(/\|+/g, '|') // collapse multiple |
                    .trim();
                body.wrapper.transactions.trade.tradeComments.comments.push({
                    "commentType": "70",
                    "comment": comment70
                });
            }

            // Tag 32A (in orderTransactionDetails, not otherSuplDetails)
            if (!body.wrapper.transactions.trade.tradeOrderDetails.orderTransactionDetails) {
                body.wrapper.transactions.trade.tradeOrderDetails.orderTransactionDetails = {
                    orderAmountDetail: []
                };
            }
            body.wrapper.transactions.trade.tradeOrderDetails.orderTransactionDetails.orderAmountDetail =
                body.wrapper.transactions.trade.tradeOrderDetails.orderTransactionDetails.orderAmountDetail.filter(function(item) {
                    return item.amount && item.amount !== '' && item.currencyDetails && item.currencyDetails.currencyCode && item.currencyDetails.currencyCode !== '';
                });


            return JSON.stringify(body, null, 4);
        } catch (e) {
            gs.error('Error in prepareMT103Payload: ' + e.message);
        }
    },

    // Prepares payload for MT202 message (explicit, modular tag logic)
    // This function builds the MT202 message structure, including all required tags and fields.
    // Uses helper functions to add party and account details in the correct SWIFT/CMF order.
    prepareMT202Payload: function(source_type, senderbic, transactionReference, relatedReference, valuedate, currency, transactionAmount, customerOrderType, orderingInstitutionBIC, orderingInstitutionName, orderingInstitutionAddress, orderingInstitutionIdentifierCode, sendersCorrespondentBIC, sendersCorrespondentName, sendersCorrespondentAddress, sendersCorrespondentIdentifierCode, sendersCorrespondentLocation, intermediaryBankBIC, intermediaryBankName, intermediaryBankAddress, intermediaryBankIdentifierCode, beneficiaryBankBIC, beneficiaryBankName, beneficiaryBankAddress, beneficiaryBankIdentifierCode, beneficiaryInstitutionBIC, beneficiaryInstitutionName, beneficiaryInstitutionAddress, beneficiaryInstitutionIdentifierCode, senderToReceiverInformation, firstReceivedTimestamp, receiverbic, swift_message) {
        try {
            // Helper to parse outputDate/outputTime from First Received Timestamp
            var outputDate = ''; // Initialize outputDate as empty string
            var outputTime = ''; // Initialize outputTime as empty string
            if (firstReceivedTimestamp && typeof firstReceivedTimestamp === 'string') { // Check if firstReceivedTimestamp exists and is a string
                var dateMatch = firstReceivedTimestamp.match(/(\d{4}-\d{2}-\d{2})/); // Extract date in yyyy-MM-dd format
                var timeMatch = firstReceivedTimestamp.match(/(\d{2})\.(\d{2})\.\d{2}/); // Only extract hour and minute
                if (dateMatch) outputDate = dateMatch[1]; // If date found, assign to outputDate
                if (timeMatch) {
                    outputTime = timeMatch[1] + timeMatch[2]; // Format as HHMM (no colon)
                }
            }
            // Build the MT202 payload structure
            var body = {
                "wrapper": {
                    "transactions": {
                        "sourceName": source_type,
                        "clientShortName": (source_type === 'FAX' || source_type === 'EMAIL' || !senderbic || typeof senderbic !== 'string') ? 'NULL' : senderbic,
                        "trade": {
                            "tradeOrderDetails": {
                                "customerReference": transactionReference,
                                "customerOrderType": customerOrderType || "NEWM",
                                // Only include relatedCustomerReference if relatedReference is non-empty
                                ...(relatedReference && relatedReference.trim() !== '' ? {
                                    "relatedCustomerReference": relatedReference
                                } : {}),
                                "orderValueDate": valuedate,
                                "orderTransactionDetails": {
                                    "orderAmountDetail": [{
                                        "amountType": "32A",
                                        "amount": transactionAmount,
                                        "currencyDetails": {
                                            "currencyCode": currency
                                        }
                                    }]
                                }
                            },
                            "tradeComments": {
                                "comments": [
                                    // Tag 72: Sender to Receiver Information
                                    senderToReceiverInformation && senderToReceiverInformation.trim() !== '' ? (function() {
                                        // Upstream now splits at 35 chars using newlines. Convert any newline(s) to '|'
                                        var comment72 = senderToReceiverInformation
                                            .replace(/\\n+/g, '|') // literal \n → |
                                            .replace(/\r?\n+/g, '|') // real newlines → |
                                            .replace(/\|+/g, '|') // collapse multiple |
                                            .trim();
                                        return {
                                            "commentType": "72",
                                            "comment": comment72
                                        };
                                    })() : undefined
                                ].filter(Boolean),
                            },
                            "partiesInvolved": {
                                "partyRoleDetails": []
                            },
                            "accountsInvolved": {
                                "tradeAccountDetails": []
                            },
                            "cashTrade": {
                                "transactionType": "PAYM",
                                "transactionSubType": "FITRF"
                            },
                            "tradeSuplDetails": {
                                "swiftOtherDetails": {
                                    "swiftOtherDetail": [].concat(
                                        // Include outputDate and outputTime only if they have values
                                        (function() {
                                            var details = [];
                                            if (outputDate) {
                                                details.push({
                                                    "fieldName": "outputDate",
                                                    "swiftFieldName": "2",
                                                    "fieldValue": outputDate
                                                });
                                            }
                                            if (outputTime) {
                                                details.push({
                                                    "fieldName": "outputTime",
                                                    "swiftFieldName": "2",
                                                    "fieldValue": outputTime
                                                });
                                            }
                                            return details;
                                        })(),
                                        [{
                                                "fieldName": "msgType",
                                                "swiftFieldName": "2",
                                                // Extracts the numeric part from swift_message (e.g., 'MT202' -> '202').
                                                // If swift_message is already numeric or does not match, returns as is.
                                                "fieldValue": (function() {
                                                    if (typeof swift_message === 'string') {
                                                        var match = swift_message.match(/MT(\d+)/i);
                                                        if (match && match[1]) {
                                                            return match[1];
                                                        }
                                                    }
                                                    // fallback: extract digits if present
                                                    var digits = (swift_message + '').match(/\d+/);
                                                    return digits ? digits[0] : swift_message;
                                                })()
                                            },
                                            {
                                                "fieldName": "senderBIC",
                                                "swiftFieldName": "2",
                                                "fieldValue": senderbic
                                            },
                                            {
                                                "fieldName": "receiverBIC",
                                                "swiftFieldName": "1",
                                                "fieldValue": receiverbic
                                            }
                                        ].filter(function(detail) {
                                            // Remove senderBIC/receiverBIC if value is null/empty
                                            if ((detail.fieldName === "senderBIC" || detail.fieldName === "receiverBIC") && (!detail.fieldValue || detail.fieldValue === '' || detail.fieldValue === null)) {
                                                return false;
                                            }
                                            return true;
                                        })
                                    )
                                }
                            }
                        }
                    }
                }
            };

            // Helper functions
            // Adds a party with a specific role and BIC
            var addPartyRoleDetails = function(roleType, partyIdType, partyId) {
                if (partyId && partyId.trim() !== '') {
                    body.wrapper.transactions.trade.partiesInvolved.partyRoleDetails.push({
                        "partyRoleType": roleType,
                        "partyDetails": {
                            "partyIdentifiers": {
                                "partyIds": [{
                                    "partyIdType": partyIdType,
                                    "partyId": partyId
                                }]
                            }
                        }
                    });
                }
            };

            // Adds a party with a specific role and name (when BIC is not present)
            var addPartyNameDetails = function(roleType, partyName) {
                if (partyName && partyName.trim() !== '') {
                    var details = {
                        "partyRoleType": roleType,
                        "partyDetails": {
                            "partyName": partyName
                        }
                    };
                    body.wrapper.transactions.trade.partiesInvolved.partyRoleDetails.push(details);
                }
            };

            // Adds an account with a specific role and account number/identifier
            var addAccountDetails = function(roleType, accountNumber) {
                if (accountNumber && accountNumber.trim() !== '') {
                    body.wrapper.transactions.trade.accountsInvolved.tradeAccountDetails.push({
                        "accountRoleType": roleType,
                        "accountDetails": {
                            "accountId": accountNumber
                        }
                    });
                }
            };

            // Tag 52: Ordering Institution
            // 52A: if both Account ID and BIC have value
            if (orderingInstitutionIdentifierCode && orderingInstitutionIdentifierCode.trim() !== '' && orderingInstitutionBIC && orderingInstitutionBIC.trim() !== '') {
                addAccountDetails('52A', orderingInstitutionIdentifierCode);
                addPartyRoleDetails('52A', 'BIC', orderingInstitutionBIC);
                // 52A: if only BIC has value
            } else if (orderingInstitutionBIC && orderingInstitutionBIC.trim() !== '') {
                addPartyRoleDetails('52A', 'BIC', orderingInstitutionBIC);
                // 52D: if BIC is empty and NAME and address has value
            } else if (orderingInstitutionName) {
                addAccountDetails('52D', orderingInstitutionIdentifierCode);
                addPartyNameDetails('52D', orderingInstitutionName);
            }

            // Tag 53: Sender's Correspondent
            // 53B: If account id has value
            if (sendersCorrespondentIdentifierCode && sendersCorrespondentIdentifierCode.trim() !== '') {
                addAccountDetails('53B', sendersCorrespondentIdentifierCode);
            }

            // Tag 56: Intermediary Bank
            // 56A: If BIC has value
            if (intermediaryBankBIC && intermediaryBankBIC.trim() !== '') {
                addAccountDetails('56A', intermediaryBankIdentifierCode);
                addPartyRoleDetails('56A', 'BIC', intermediaryBankBIC);
                // 56D: If BIC is empty and NAME has value
            } else if ((!intermediaryBankBIC || intermediaryBankBIC.trim() === '') && intermediaryBankName && intermediaryBankName.trim() !== '') {
                addAccountDetails('56D', intermediaryBankIdentifierCode);
                addPartyNameDetails('56D', intermediaryBankName);
            }

            // Tag 57: Beneficiary Bank
            // 57A: If BIC has value
            if (beneficiaryBankBIC && beneficiaryBankBIC.trim() !== '') {
                addAccountDetails('57A', beneficiaryBankIdentifierCode);
                addPartyRoleDetails('57A', 'BIC', beneficiaryBankBIC);
                // 57D: If BIC is empty and NAME has value
            } else if ((!beneficiaryBankBIC || beneficiaryBankBIC.trim() === '') && beneficiaryBankName && beneficiaryBankName.trim() !== '') {
                addAccountDetails('57D', beneficiaryBankIdentifierCode);
                addPartyNameDetails('57D', beneficiaryBankName);
            }

            // Tag 58: Beneficiary Institution
            // 58A: If BIC has value
            if (beneficiaryInstitutionBIC && beneficiaryInstitutionBIC.trim() !== '') {
                addAccountDetails('58A', beneficiaryInstitutionIdentifierCode);
                addPartyRoleDetails('58A', 'BIC', beneficiaryInstitutionBIC);
                // 58D: If BIC is empty and NAME has value
            } else if ((!beneficiaryInstitutionBIC || beneficiaryInstitutionBIC.trim() === '') && beneficiaryInstitutionName && beneficiaryInstitutionName.trim() !== '') {
                addAccountDetails('58D', beneficiaryInstitutionIdentifierCode);
                addPartyNameDetails('58D', beneficiaryInstitutionName);
            }

            // Tag 32A (in orderTransactionDetails, not otherSuplDetails)
            if (!body.wrapper.transactions.trade.tradeOrderDetails.orderTransactionDetails) {
                body.wrapper.transactions.trade.tradeOrderDetails.orderTransactionDetails = {
                    orderAmountDetail: []
                };
            }

            body.wrapper.transactions.trade.tradeOrderDetails.orderTransactionDetails.orderAmountDetail =
                body.wrapper.transactions.trade.tradeOrderDetails.orderTransactionDetails.orderAmountDetail.filter(function(item) {
                    return item.amount && item.amount !== '' && item.currencyDetails && item.currencyDetails.currencyCode && item.currencyDetails.currencyCode !== '';
                });

            if (!body.wrapper.transactions.trade.tradeOrderDetails.orderValueDate) {
                body.wrapper.transactions.trade.tradeOrderDetails.orderValueDate = '';
            }

            return JSON.stringify(body, null, 4);
        } catch (e) {
            gs.error('Error in prepareMT202Payload: ' + e.message);
        }
    },

    /// Creates a standard ITM header for messages
    createItmHeader: function(caseId, legalEntity, action, messageType, owningBusiness, cmf) {
        try {
            gs.info('ITM HEADER: sourceUniqueRef=' + (caseId + '|Treasury') + ', messageType=' + messageType + ', legalEntity=' + legalEntity);
            return {
                "instructions": [{
                    "sourceUniqueRef": caseId + '|Treasury', // Append '|Treasury' as separator
                    "clientAccountRegion": "HBAP",
                    "instructionType": "NEWM", // Always set to NEWM as per ITM spec
                    "transactionType": messageType === 'MT103' || messageType === 'MT202' ? 'PAYM' : '',
                    "transactionSubType": messageType === 'MT103' ? 'CTRF' : messageType === 'MT202' ? 'FITRF' : '',
                    "messageCategory": messageType,
                    "productIdentifier": "TRS",
                    "countryIdentifier": "HK",
                    "payload": JSON.stringify(cmf) // ITM expects payload as a string
                }]
            };
        } catch (e) {
            gs.error('Error in createItmHeader: ' + e.message);
            return null; // Return null or handle the error appropriately
        }
    },

    // Formats date to 'yyyy-MM-dd' (ServiceNow GlideDateTime)
    formatDate: function(dateValue) {
        try {
            if (!dateValue) return "";
            var glideDateTime = new GlideDateTime(dateValue);
            var formatted = glideDateTime.getDate().getByFormat('yyyy-MM-dd');
            return formatted;
        } catch (error) {
            gs.error('Error formatting date: ' + error.message);
            return "";
        }
    },

    // Removes commas from a string (for numeric fields)
    removeCommas: function(integerString) {
        try {
            var result = integerString ? integerString.replace(/,/g, '') : '';
            return result;
        } catch (e) {
            gs.error('Error in removeCommas: ' + e.message);
            return '';
        }
    },

    xMatterAlert(severity, txt) {
        try {
            new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent(severity || "WARNING", txt, 'MSSiQubeSN');
        } catch (errorInfo) {
            gs.error('Treasury - Script Include - MSS_Treasury_ITM_Utils: Function : xMatterAlert :- Unknown exception while processing' + errorInfo.message);
        }
    },

    errorLogAndXmatterAlert(severity, message) {
        const logPrefix = "Treasury - Script Include - MSS_Treasury_ITM_Utils: ";
        const finalMessage = logPrefix + message;
        gs.error(finalMessage);
        this.xMatterAlert(severity, finalMessage);
    },

    type: 'MSS_Treasury_ITM_Utils'
};
